import type { Adjustment } from "@/lib/editing/schema";

export type SceneContext = "portrait" | "street" | "landscape" | "interior" | "architecture" | "fashion" | "documentary" | "action" | "food" | "nature" | "automotive" | "nightlife" | "travel" | "fine-art";
export type LightingCharacter = "soft" | "hard" | "mixed" | "backlit" | "practical" | "low-key" | "high-key" | "available" | "diffused" | "side-lit" | "even";
export type PaletteFamily = "neutral" | "warm" | "cool" | "cyan-amber" | "earth" | "pastel" | "neon" | "monochrome" | "desaturated" | "vivid";

export interface CinematicReference {
  title: string;
  year: number;
  /** Visual study only; never implies a right to reproduce frames, LUTs or protected assets. */
  note: string;
}

export interface CinematicLook {
  id: string;
  name: string;
  intent: string;
  visualTraits: string[];
  keywords: string[];
  sceneContexts: SceneContext[];
  lighting: LightingCharacter[];
  palette: PaletteFamily[];
  mood: string[];
  cameraLanguage: string[];
  referenceWorks: CinematicReference[];
  globalBias: Partial<Adjustment>;
  caution: string;
  implementationNote: string;
}

type LookInput = Omit<CinematicLook, "visualTraits" | "keywords" | "sceneContexts" | "lighting" | "palette" | "mood" | "cameraLanguage" | "referenceWorks" | "globalBias" | "caution" | "implementationNote"> & {
  traits: string[];
  keywords: string[];
  scenes: SceneContext[];
  light: LightingCharacter[];
  palette: PaletteFamily[];
  mood: string[];
  camera?: string[];
  refs?: Array<[string, number, string]>;
  bias?: Partial<Adjustment>;
  caution: string;
  note?: string;
};

const defineLook = (input: LookInput): CinematicLook => ({
  id: input.id,
  name: input.name,
  intent: input.intent,
  visualTraits: input.traits,
  keywords: input.keywords,
  sceneContexts: input.scenes,
  lighting: input.light,
  palette: input.palette,
  mood: input.mood,
  cameraLanguage: input.camera ?? [],
  referenceWorks: (input.refs ?? []).map(([title, year, note]) => ({ title, year, note })),
  globalBias: input.bias ?? {},
  caution: input.caution,
  implementationNote: input.note ?? "Aplicar somente os ajustes suportados pelo renderizador atual; não simular óptica, iluminação física ou informação ausente.",
});

