const TOKEN_ALIASES: Record<string, string[]> = {
  noite:["night","nocturne","noir","dark"], noturna:["night","nocturne","noir"], noturno:["night","nocturne","noir"],
  chuva:["rain","wet","reflections"], chuvoso:["rain","wet"], molhada:["wet","rain","reflections"],
  por:["sunset"], sol:["sun","sunlight","golden"], nascer:["sunrise","dawn"], entardecer:["dusk","twilight","sunset"],
  quente:["warm","amber","tungsten"], frio:["cool","blue","cyan"], azul:["blue","cool","cyan"], laranja:["orange","amber","warm"],
  verde:["green","forest","earth"], vermelho:["red","crimson"], rosa:["pink","pastel","magenta"],
  janela:["window","light"], luz:["light","lighting"],
  retrato:["portrait"], pessoa:["portrait","skin tones"], rosto:["portrait","skin tones"], pessoas:["portrait","skin tones"],
  cidade:["city","urban","street"], urbano:["urban","city"], rua:["street","urban"], floresta:["forest","woods","green"],
  paisagem:["landscape"], arquitetura:["architecture"], comida:["food"], carro:["car","automotive"], carroceria:["automotive","car"],
  filme:["film","analog","cinema"], pelicula:["film","analog"], analogico:["analog","film","vintage"], vintage:["retro","analog"],
  sonho:["dream","dreamlike"], triste:["sad","melancholic"], romântico:["romantic"], romantico:["romantic"],
  documental:["documentary"], documentalismo:["documentary"], industrial:["industrial"], neve:["snow","winter","ice"],
  deserto:["desert","sand","earth"], neon:["neon"], fumaça:["smoke","fog","haze"], nevoa:["fog","mist","haze"],
  nublado:["overcast","cloudy","diffused"], difusa:["diffused","soft"], difuso:["diffused","soft"],
};

const normalize = (value: string): string => value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, " ").trim();
const tokenize = (value: string): string[] => normalize(value).split(/\s+/).filter((token) => token.length > 1);

function expandedQueryTokens(query: string): Set<string> {
  const expanded = new Set<string>();
  for (const token of tokenize(query)) {
    expanded.add(token);
    for (const alias of TOKEN_ALIASES[token] ?? []) {
      for (const aliasToken of tokenize(alias)) expanded.add(aliasToken);
    }
  }
  return expanded;
}

/** Hybrid lexical retrieval. It is deterministic and intentionally does not invent semantic similarity. */
export function retrieveCinematicLooks(query: string, limit = 4): CinematicLook[] {
  if (!query.trim() || !Number.isFinite(limit) || limit <= 0) return [];
  const queryTokens = expandedQueryTokens(query);
  if (queryTokens.size === 0) return [];
  const normalizedQuery = normalize(query);
  return CINEMATIC_CATALOG
    .map((look) => {
      const nameTokens = tokenize(look.name);
      const keywordTokens = tokenize(look.keywords.join(" "));
      const intentTokens = tokenize(look.intent);
      const visualTokens = tokenize([
        ...look.visualTraits, ...look.sceneContexts, ...look.lighting, ...look.palette,
        ...look.mood, ...look.cameraLanguage, ...look.referenceWorks.map((ref) => ref.title),
      ].join(" "));
      let score = 0;
      for (const token of queryTokens) {
        if (nameTokens.includes(token)) score += 5;
        if (keywordTokens.includes(token)) score += 4;
        if (intentTokens.includes(token)) score += 2;
        if (visualTokens.includes(token)) score += 1;
      }
      if (normalizedQuery.length >= 4 && normalize(look.name).includes(normalizedQuery)) score += 8;
      return { look, score };
    })
    .filter((entry) => entry.score > 0)
    .sort((a, b) => b.score - a.score || a.look.id.localeCompare(b.look.id))
    .slice(0, Math.floor(limit))
    .map(({ look }) => look);
}
